const isManual = $execution.mode === 'manual';

// Final correction - safe input envelope. $input.first().json is always
// an object (n8n guarantees this for the trigger's own output), but the
// webhook body it carries - or, on the Manual Trigger path, the raw item
// itself when no 'body' wrapper is present - can be anything a caller
// sends: null, an array, a string, a number, or a genuine object. None of
// those ever throws here; a non-object is rejected with a bounded
// validationError that never echoes the raw input.
const rawInput = $input.first().json;
const rawInputIsPlainObject = rawInput !== null && typeof rawInput === 'object' && !Array.isArray(rawInput);
const body = rawInputIsPlainObject && rawInput.body !== undefined ? rawInput.body : rawInput;

if (body === null || typeof body !== 'object' || Array.isArray(body)) {
  return [{ json: { isManual, validationError: 'Request body must be a JSON object.' } }];
}

// Pure-JavaScript UUID v4 generator (Correction V2: no Node built-in
// module import here - n8n Cloud code nodes run in a restricted sandbox
// and must not depend on one). DEV/TESTING ONLY - never invoked on the
// production Webhook path, and never a cryptographically strong id; it
// only needs to be unique within this one workflow execution.
function generateTemporaryUuidV4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = Math.floor(Math.random() * 16);
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

// isManual is preserved on EVERY returned json (success or
// validationError) so downstream IF nodes never need to re-derive
// $execution.mode themselves - a single, explicit source of truth for
// the manual-vs-production routing split.

let invocationId = body.invocation_id;
if (!invocationId) {
  if (!isManual) {
    // Production Webhook path: invocation_id is mandatory. Never generated
    // silently here - fail validation instead, before any POST /jobs call.
    return [{ json: { isManual, validationError: 'invocation_id is required for a production request and was not provided.' } }];
  }
  // DEV/TESTING ONLY (Manual Trigger path): a temporary UUID, stable only
  // within this one workflow execution. Never reachable from the
  // production Webhook Trigger.
  invocationId = generateTemporaryUuidV4();
}

if (typeof invocationId !== 'string') {
  return [{ json: { isManual, validationError: 'invocation_id must be a string.' } }];
}
invocationId = invocationId.trim();
const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!UUID_PATTERN.test(invocationId)) {
  return [{ json: { isManual, validationError: 'invocation_id must be a canonical UUID.' } }];
}
invocationId = invocationId.toLowerCase();

// Final correction - FINQUEST_API_BASE_URL/FINQUEST_KEY_ID are parsed and
// normalized exactly ONCE, here. This is the ONLY node in the workflow
// allowed to read $vars.FINQUEST_API_BASE_URL / $vars.FINQUEST_KEY_ID -
// every FinQuest HTTP Request node downstream uses the validated
// $json.apiBaseUrl / $json.keyId carried in the workflow state instead.
const configBaseUrlRaw = $vars.FINQUEST_API_BASE_URL;
if (typeof configBaseUrlRaw !== 'string' || configBaseUrlRaw.trim() === '') {
  return [{ json: { isManual, validationError: 'FINQUEST_API_BASE_URL is required and must be configured - there is no Docker-network fallback.' } }];
}

let parsedBaseUrl;
try {
  parsedBaseUrl = new URL(configBaseUrlRaw.trim());
} catch (err) {
  return [{ json: { isManual, validationError: 'FINQUEST_API_BASE_URL must be a valid URL.' } }];
}
if (!parsedBaseUrl.hostname) {
  return [{ json: { isManual, validationError: 'FINQUEST_API_BASE_URL must include a hostname.' } }];
}
if (parsedBaseUrl.username || parsedBaseUrl.password) {
  return [{ json: { isManual, validationError: 'FINQUEST_API_BASE_URL must not contain embedded credentials.' } }];
}
if (!isManual && parsedBaseUrl.protocol !== 'https:') {
  return [{ json: { isManual, validationError: 'FINQUEST_API_BASE_URL must be an HTTPS URL for a production request.' } }];
}
// Trailing slash(es) removed so every downstream HTTP node can safely
// concatenate a leading-slash path without ever producing a double slash.
const apiBaseUrl = parsedBaseUrl.toString().replace(/\/+$/, '');

const configKeyIdRaw = $vars.FINQUEST_KEY_ID;
if (typeof configKeyIdRaw !== 'string' || configKeyIdRaw.trim() === '') {
  return [{ json: { isManual, validationError: 'FINQUEST_KEY_ID is required and must be configured.' } }];
}
const keyId = configKeyIdRaw.trim();

// Final correction - minimal, safety/routing-critical request validation
// only. The FinQuest backend's Pydantic model remains authoritative for
// exact length limits, complete SEC CIK validation, concept
// limits/deduplication, and every remaining parameter constraint - this
// workflow deliberately does not duplicate it. A request that fails one
// of these minimal checks never reaches Trigger FinQuest Job; a request
// that passes them but is still rejected by the backend is now handled
// gracefully post-POST without crashing this execution (see 'Classify
// Trigger Response').
const scope = body.scope;
let originalQuestion = body.original_question;
let subjectSecurityId = body.subject_security_id;
let subjectRawText = body.subject_raw_text;
const secCik = body.sec_cik;
const secConcepts = body.sec_concepts;

if (typeof originalQuestion !== 'string') {
  return [{ json: { isManual, validationError: 'original_question must be a string.' } }];
}
originalQuestion = originalQuestion.trim();
if (originalQuestion === '') {
  return [{ json: { isManual, validationError: 'original_question must not be blank.' } }];
}

if (typeof subjectRawText === 'string') {
  subjectRawText = subjectRawText.trim();
  if (subjectRawText === '') {
    // Blank becomes absent - never treated as a provided subject; this is
    // routing-critical for the exactly-one-subject checks below.
    subjectRawText = undefined;
  }
} else if (subjectRawText !== undefined && subjectRawText !== null) {
  return [{ json: { isManual, validationError: 'subject_raw_text must be a string.' } }];
} else {
  subjectRawText = undefined;
}

if (typeof subjectSecurityId === 'string') {
  subjectSecurityId = subjectSecurityId.trim();
  if (subjectSecurityId === '') {
    subjectSecurityId = undefined;
  }
} else if (subjectSecurityId !== undefined && subjectSecurityId !== null) {
  return [{ json: { isManual, validationError: 'subject_security_id must be a string.' } }];
} else {
  subjectSecurityId = undefined;
}

const hasSecConcepts = Array.isArray(secConcepts) ? secConcepts.length > 0 : Boolean(secConcepts);

const SUPPORTED_SCOPES = ['GENERAL_QUESTION', 'NEWS_SCAN', 'ANALYST_SENTIMENT', 'FINANCIAL_FILING_REVIEW', 'COMPANY_OVERVIEW'];
if (!SUPPORTED_SCOPES.includes(scope)) {
  return [{ json: { isManual, validationError: `Unsupported or missing scope '${scope}'. LIVE_RESEARCH_RUN_EXECUTION does not support MARKET_DATA_SNAPSHOT.` } }];
}

const subjectCount = [subjectSecurityId, subjectRawText].filter((v) => v !== undefined).length;

if (scope === 'GENERAL_QUESTION') {
  if (subjectCount !== 0) {
    return [{ json: { isManual, validationError: 'GENERAL_QUESTION must not include a subject.' } }];
  }
} else if (scope === 'NEWS_SCAN' || scope === 'ANALYST_SENTIMENT') {
  if (subjectCount !== 1) {
    return [{ json: { isManual, validationError: `${scope} requires exactly one of subject_security_id or subject_raw_text.` } }];
  }
} else if (scope === 'FINANCIAL_FILING_REVIEW') {
  if (subjectCount !== 1) {
    return [{ json: { isManual, validationError: 'FINANCIAL_FILING_REVIEW requires exactly one of subject_security_id or subject_raw_text.' } }];
  }
  if (!secCik) {
    return [{ json: { isManual, validationError: 'FINANCIAL_FILING_REVIEW requires sec_cik.' } }];
  }
} else if (scope === 'COMPANY_OVERVIEW') {
  if (subjectCount !== 1) {
    return [{ json: { isManual, validationError: 'COMPANY_OVERVIEW requires exactly one of subject_security_id or subject_raw_text.' } }];
  }
  if (!secCik) {
    return [{ json: { isManual, validationError: 'COMPANY_OVERVIEW requires sec_cik.' } }];
  }
  if (!hasSecConcepts) {
    return [{ json: { isManual, validationError: 'COMPANY_OVERVIEW requires a non-empty sec_concepts array.' } }];
  }
}

const parameters = { original_question: originalQuestion, scope };
if (subjectSecurityId) parameters.subject_security_id = subjectSecurityId;
if (subjectRawText) parameters.subject_raw_text = subjectRawText;
if (secCik) parameters.sec_cik = secCik;
if (secConcepts !== undefined && secConcepts !== null) parameters.sec_concepts = secConcepts;

// Derived per-invocation identifiers (Phase G2C): never derived from
// question content, never the n8n execution ID alone. The same
// invocation_id (reused across retries of one logical request) always
// produces the same X-FinQuest-Request-ID and Idempotency-Key; a new
// invocation_id - even for byte-identical parameters - always produces
// different values, so it creates a different durable job.
return [{
  json: {
    isManual,
    jobType: 'LIVE_RESEARCH_RUN_EXECUTION',
    parameters,
    invocationId,
    externalRequestId: `livequery-req:${invocationId}`,
    idempotencyKey: `livequery-idem:${invocationId}`,
    apiBaseUrl,
    keyId,
  },
}];

const input = $input.first().json;
const jobId = input.jobId;
if (!jobId) { throw new Error('FinQuest did not return a job_id'); }
const request = $('Validate / Build Request').first().json;
const waitSeconds = 15;
// Primary deadline: computed ONCE, here - never re-derived from an
// attempt counter alone. maxAttempts is only a bounded secondary safety
// guard (~40 minutes at a 15-second interval).
const deadlineAt = Date.now() + 40 * 60 * 1000;
const maxAttempts = 160;
return [{ json: {
  jobId,
  invocationId: request.invocationId,
  apiBaseUrl: request.apiBaseUrl,
  keyId: request.keyId,
  attempt: 0,
  maxAttempts,
  waitSeconds,
  deadlineAt,
} }];

const polled = $input.first().json;
const state = $('Init Polling State').first().json;
// Correction V2: 'Increment Poll Attempt' has not run yet on the first
// poll iteration (it only executes after the loop's first pass through
// 'Is Terminal Or Timed Out?'), so its output must never be dereferenced
// before confirming it actually executed - doing so throws in n8n rather
// than returning a safe sentinel. isExecuted is checked first; .first()
// on that node reference is only ever called when it is true.
const incrementNode = $('Increment Poll Attempt');
const attempt = incrementNode.isExecuted ? incrementNode.first().json.attempt : state.attempt;
const timedOut = Date.now() > state.deadlineAt;
return [{ json: {
  jobId: state.jobId,
  invocationId: state.invocationId,
  apiBaseUrl: state.apiBaseUrl,
  keyId: state.keyId,
  waitSeconds: state.waitSeconds,
  maxAttempts: state.maxAttempts,
  deadlineAt: state.deadlineAt,
  attempt,
  status: polled.status,
  resultSummary: polled.result_summary || {},
  timedOut,
} }];

const evidencePage = $input.first().json;
const state = $('Merge Polling State').first().json;
return [{ json: {
  workflowResult: 'SUCCESS_WITH_EVIDENCE',
  jobId: state.jobId,
  invocationId: state.invocationId,
  researchRunStatus: state.resultSummary.research_run_status,
  evidenceRecorded: state.resultSummary.evidence_recorded,
  evidence: evidencePage.items,
  hasMoreEvidence: evidencePage.has_more,
} }];

const state = $input.first().json;
return [{ json: {
  workflowResult: 'SUCCESS_NO_EVIDENCE',
  jobId: state.jobId,
  invocationId: state.invocationId,
  researchRunStatus: state.resultSummary.research_run_status,
  failureCategory: state.resultSummary.failure_category,
  evidenceRecorded: 0,
} }];

const state = $input.first().json;
return [{ json: {
  workflowResult: 'OPERATIONAL_FAILURE',
  jobId: state.jobId,
  invocationId: state.invocationId,
  status: state.status,
  resultSummary: state.resultSummary,
} }];

const state = $input.first().json;
return [{ json: {
  workflowResult: 'POLLING_TIMEOUT',
  jobId: state.jobId,
  invocationId: state.invocationId,
  lastKnownStatus: state.status,
  attempts: state.attempt,
} }];

const state = $input.first().json;
return [{ json: {
  accepted: false,
  validation_error: state.validationError,
} }];

const classified = $input.first().json;
const request = $('Validate / Build Request').first().json;
return [{ json: {
  accepted: true,
  job_id: classified.jobId,
  invocation_id: request.invocationId,
  status: 'POLLING_STARTED',
} }];

const item = $input.first().json;
const request = $('Validate / Build Request').first().json;

// Trigger FinQuest Job uses 'Never Error' + 'Full Response' (final
// correction): a non-2xx HTTP response is returned as normal item data
// (statusCode/headers/body) instead of throwing. It also sets
// onError=continueRegularOutput, so a genuine transport-level failure
// (DNS, connection refused, timeout - no HTTP response at all) is
// likewise converted into a normal item (carrying only an `error` field
// and no statusCode) instead of crashing this execution.
const statusCode = typeof item.statusCode === 'number' ? item.statusCode : undefined;
const responseBody = item.body;

let outcome;
let jobId;
if (statusCode === undefined) {
  outcome = 'INFRA_FAILURE';
} else if (statusCode >= 200 && statusCode < 300) {
  jobId = (responseBody && responseBody.job && responseBody.job.job_id) || (responseBody && responseBody.job_id);
  outcome = jobId ? 'ACCEPTED' : 'INFRA_FAILURE';
} else if (statusCode >= 400 && statusCode < 500) {
  outcome = 'REJECTED';
} else {
  // Any 5xx, or an unexpected 1xx/3xx - treated as an infrastructure/
  // server failure. Never silently polled.
  outcome = 'INFRA_FAILURE';
}

return [{ json: {
  outcome,
  statusCode: statusCode === undefined ? null : statusCode,
  jobId,
  isManual: request.isManual,
} }];

const classified = $input.first().json;
const request = $('Validate / Build Request').first().json;
return [{ json: {
  isManual: true,
  invocationId: request.invocationId,
  validationError: `FinQuest rejected the request (HTTP ${classified.statusCode}).`,
} }];

const classified = $input.first().json;
return [{ json: {
  accepted: false,
  validation_error: `FinQuest rejected the request (HTTP ${classified.statusCode}).`,
} }];

const classified = $input.first().json;
const request = $('Validate / Build Request').first().json;
return [{ json: {
  workflowResult: 'OPERATIONAL_FAILURE',
  invocationId: request.invocationId,
  status: classified.statusCode === null ? 'TRANSPORT_ERROR' : `HTTP_${classified.statusCode}`,
} }];

const classified = $input.first().json;
return [{ json: {
  accepted: false,
  operational_error: 'FinQuest is currently unavailable. Please retry later.',
} }];
